<template><view class="p"><view class="nav"><text @click="back">‹</text><text>商品专属回复</text><text @click="load">⟳</text></view><scroll-view scroll-y class="list"><view class="card" v-for="r in rows" :key="r.id"><view class="top"><text class="name">{{r.replyName||r.name||('回复 #'+r.id)}}</text><text :class="['tag',r.enabled?'on':'off']">{{r.enabled?'启用':'停用'}}</text></view><text class="desc">商品 {{r.itemId||'-'}} · {{r.triggerScene||'-'}}</text><text class="content">{{r.replyContent||r.content||'-'}}</text></view><view v-if="!rows.length" class="hint">暂无商品专属回复</view></scroll-view></view></template>
<script setup lang="ts">import{onMounted,ref}from'vue';import{listItemReplies}from'@/api/bot';const rows=ref<any[]>([]);async function load(){try{const r:any=await listItemReplies({page:1,size:100});rows.value=Array.isArray(r)?r:(r?.records||[])}catch(e:any){uni.showToast({title:e?.message||'加载失败',icon:'none'})}}function back(){uni.navigateBack({fail:()=>uni.switchTab({url:'/pages/profile/index'})})}onMounted(load)</script><style scoped lang="scss">.p{min-height:100vh;background:#f5f5f7}.nav{height:88rpx;background:#fff;display:flex;align-items:center;justify-content:space-between;padding:0 24rpx;font-size:32rpx;font-weight:700}.nav text:first-child{font-size:48rpx;color:#6b7280}.nav text:last-child{font-size:34rpx;color:#4f46e5}.list{height:calc(100vh - 88rpx);padding:24rpx}.card{background:#fff;border-radius:24rpx;padding:24rpx;margin-bottom:16rpx}.top{display:flex;justify-content:space-between}.name{font-weight:800;color:#111827}.tag{font-size:22rpx;padding:4rpx 12rpx;border-radius:999rpx}.on{background:#dcfce7;color:#16a34a}.off{background:#f3f4f6;color:#6b7280}.desc,.content{display:block;color:#6b7280;font-size:24rpx;margin-top:10rpx}.hint{text-align:center;color:#9ca3af;padding:40rpx}</style>